// Local review helpers; bundled runtime contains the same configuration functions.
export function replaceShellConfig(dashboard, expected, next) {
  const copy=structuredClone(dashboard);
  const matches=[];
  const visit=node=>{if(!node||typeof node!=='object')return;if(node.type==='custom:taqani-shell')matches.push(node);for(const value of Object.values(node))if(value&&typeof value==='object')Array.isArray(value)?value.forEach(visit):visit(value);};
  visit(copy);
  if(matches.length!==1)throw new Error('توجد أكثر من بطاقة أو البطاقة غير موجودة؛ استخدم محرر Home Assistant.');
  if(JSON.stringify(matches[0])!==JSON.stringify(expected))throw new Error('تغيرت الإعدادات من شاشة أخرى. أعد فتح الإدارة قبل الحفظ.');
  Object.keys(matches[0]).forEach(k=>delete matches[0][k]);Object.assign(matches[0],next);
  return copy;
}
export async function saveSettings(hass, path, expected, next) {
  if(!hass.user?.is_admin)throw new Error('صلاحية الإدارة مطلوبة.');
  const dashboard=await hass.callWS({type:'lovelace/config',url_path:path,force:true});
  const config=replaceShellConfig(dashboard,expected,next);
  await hass.callWS({type:'lovelace/config/save',url_path:path,config});
  return config;
}
// HA keys the default dashboard (/lovelace) as null; passing "lovelace" fails to load or save.
export function dashboardPath(pathname=location.pathname){const p=pathname.split('/')[1];return p&&p!=='lovelace'?p:null;}

// Only locally approved functional roles are eligible for aggregate controls.
export function scopedEntities(settings,entities,devices,areas,scope){
  const [kind,id]=scope.split(':');
  const approved=[...new Set(['lights','climates','televisions','covers'].flatMap(k=>Array.isArray(settings[k])?settings[k]:[]))];
  const allowed=entity=>{const domain=entity.split('.')[0];return (settings.lights||[]).includes(entity)&&['light','switch'].includes(domain)||(settings.climates||[]).includes(entity)&&domain==='climate'||(settings.televisions||[]).includes(entity)&&domain==='media_player'||(settings.covers||[]).includes(entity)&&domain==='cover';};
  return approved.filter(entityId=>{if(!allowed(entityId))return false;const entry=entities.find(e=>e.entity_id===entityId);if(!entry||entry.disabled_by)return false;const device=devices.find(d=>d.id===entry.device_id);if(device?.disabled_by)return false;const areaId=entry.area_id||device?.area_id;if(kind==='area')return areaId===id;if(kind==='floor')return areas.some(a=>a.area_id===areaId&&a.floor_id===id);return false;});
}
export function scopePlan(ids,states,on,services){
  const commands=[],skipped=[];
  for(const id of ids){const s=states[id];if(!s||['unknown','unavailable'].includes(s.state)){skipped.push({id,reason:'غير متاح'});continue;}const domain=id.split('.')[0],features=Number(s.attributes.supported_features)||0;let service;
    if(['light','switch'].includes(domain))service=on?'turn_on':'turn_off';
    else if(domain==='climate'){if(!(features&(on?256:128))){skipped.push({id,reason:'لا يدعم أمر التشغيل/الإيقاف المباشر؛ يلزم إعداد مناسب'});continue;}service=on?'turn_on':'turn_off';}
    else if(domain==='media_player'){if(!(features&(on?128:256))){skipped.push({id,reason:'لا يدعم تشغيل/إيقاف التلفزيون'});continue;}service=on?'turn_on':'turn_off';}
    else if(domain==='cover'){if(!(features&(on?1:2))){skipped.push({id,reason:'لا يدعم فتح/إغلاق الستار'});continue;}service=on?'open_cover':'close_cover';}
    if(!service||!services?.[domain]?.[service]){skipped.push({id,reason:'أمر غير مدعوم'});continue;}
    commands.push({domain,service,entity_id:id});
  }return {commands,skipped};
}
export async function writeRegistry(hass,kind,id,fields){
  if(!hass.user?.is_admin)throw new Error('صلاحية الإدارة مطلوبة.');
  if(!['floor','area'].includes(kind))throw new Error('سجل غير صالح');
  const name=String(fields.name||'').trim();if(!name)throw new Error('اسم المجموعة أو الغرفة مطلوب.');
  const icon=String(fields.icon||'').trim();if(icon&&!/^mdi:[a-z0-9-]+$/.test(icon))throw new Error('صيغة الأيقونة مثل mdi:home');
  const data={type:`config/${kind}_registry/${id?'update':'create'}`,name};
  if(id)data[kind+'_id']=id;
  if(icon||id)data.icon=icon||null;
  if(kind==='floor'){const level=fields.level===''?null:Number(fields.level);if(level!==null&&!Number.isInteger(level))throw new Error('ترتيب المجموعة يجب أن يكون عددًا صحيحًا.');data.level=level;}
  else if(fields.floor_id)data.floor_id=fields.floor_id;else if(id)data.floor_id=null;
  return hass.callWS(data);
}

export function initialAssignmentName(entity,state,device){
  return entity.name||state?.attributes?.friendly_name||entity.original_name||((device?.name_by_user||device?.name)?`${device.name_by_user||device.name} · ${entity.entity_id}`:entity.entity_id);
}
export function assignmentPlan(rows, original, current, areas) {
  const commands=[];
  for(const row of rows){
    const before=original.find(e=>e.entity_id===row.id),now=current.find(e=>e.entity_id===row.id);
    if(!before||!now)throw Error('قناة غير موجودة في سجل الأجهزة: '+row.id);
    if(now.disabled_by)throw Error('القناة معطلة: '+row.id);
    const name=String(row.name||'').trim()||null,area=row.area==='inherit'?null:row.area;
    if(area&&!areas.some(a=>a.area_id===area))throw Error('اختر مساحة موجودة للقناة: '+row.id);
    if(row.area==='choose')throw Error('اختر مساحة للقناة: '+row.id);
    const command={type:'config/entity_registry/update',entity_id:row.id};
    for(const [key,value] of [['name',name],['area_id',area]]){
      if(key==='name'&&Object.hasOwn(row,'initialName')&&String(row.name||'').trim()===String(row.initialName||'').trim())continue;
      if(value===(before[key]||null))continue;
      if((before[key]||null)!==(now[key]||null))throw Error('تغير اسم أو موقع القناة من شاشة أخرى. أعد فتح القسم قبل الحفظ.');
      command[key]=value;
    }
    if(Object.keys(command).length>2)commands.push(command);
  }
  return commands;
}
export async function applyAssignments(hass,commands){
  if(!hass.user?.is_admin)throw Error('صلاحية الإدارة مطلوبة');
  const completed=[];
  for(const command of commands){try{await hass.callWS(command);completed.push(command.entity_id);}catch(e){return {completed,failed:command.entity_id,message:e.message||'رفض الخادم حفظ التعيين'};}}
  return {completed};
}

