    if(this.page==='lights'){const ids=list(this.settings().lights).filter(id=>/^(light|switch)\./.test(id)&&known(this.state(id)));return this.section('الإضاءة',ids.length?this.roomCubes(ids):this.notice('لا توجد إنارة متاحة الآن.'));}
    if(this.page==='climate'){const ids=list(this.settings().climates).filter(id=>id.startsWith('climate.')&&known(this.state(id)));return this.section('التكييف',ids.length?`<div class="acs-grid">${ids.map(id=>this.climateCard(id)).join('')}</div>`:this.notice('لا توجد مكيفات متاحة الآن.'));}
