  async saveForm(form){const status=form.querySelector('[data-save-status]');const button=form.querySelector('[type=submit]');button.disabled=true;try{
    if(!this._hass?.user?.is_admin)throw new Error('صلاحية الإدارة مطلوبة.');
    const settings=structuredClone(this.settings());const group=form.dataset.settings;
    for(const [key,,type] of FORM_GROUPS[group][1]){const el=form.elements.namedItem(key);settings[key]=type.startsWith('multi:')?Array.from(el.selectedOptions).map(o=>o.value).filter(Boolean):el.value.trim();if(type==='asset'&&settings[key]&&!asset(settings[key]))throw new Error('مسارات الصور يجب أن تبدأ بـ /local/ دون روابط خارجية.');}
    if(group==='house'){settings.hidden=PANELS.filter(([id])=>!form.elements.namedItem('visible_'+id).checked).map(([id])=>id);if(settings.timezone)new Intl.DateTimeFormat('ar',{timeZone:settings.timezone}).format();}
    const next={...this.config,settings};await saveSettings(this._hass,dashboardPath(),this.config,next);this.config=next;status.textContent='تم الحفظ محليًا. إعدادات المنزل منفصلة عن تحديثات HACS.';
    }catch(e){status.textContent='لم يُحفظ: '+e.message;}finally{button.disabled=false;}
  },
  async runControl(id,mode){const s=this.state(id);if(!known(s))return;const domain=id.split('.')[0];try{
    if(mode==='unlock'){if(domain!=='lock'||!await this.confirmSheet('فتح باب المدخل','سيُرسل أمر فتح القفل الآن. تأكد أن الباب تحت نظرك.',{confirm:'فتح الباب',icon:'lock-open',tone:'amber',danger:true}))return;await this._hass.callService('lock','unlock',{entity_id:id});}
    else if(mode==='toggle'){if(!['light','switch'].includes(domain)||!list(this.settings().outdoor).includes(id))return;await this._hass.callService(domain,s.state==='on'?'turn_off':'turn_on',{entity_id:id});}
    else {if(!['script','scene'].includes(domain))return;await this._hass.callService(domain,'turn_on',{entity_id:id});}
    }catch{this.toast('لم يُنفذ الأمر. تحقق من صلاحيات الحساب وحالة الجهاز.','warn');}
  },
  async nativeCards(){if(document.hidden)return;let delay=0;for(const holder of this.shadowRoot.querySelectorAll('[data-native-camera]'))if(!holder._cam){const d=delay;delay+=350;setTimeout(()=>this.camStart(holder),d);}
    const generation=this.renderGeneration;if(!this.shadowRoot.querySelector('[data-native-entity]:empty'))return;let helpers;try{helpers=await window.loadCardHelpers();}catch{return;}if(generation!==this.renderGeneration)return;for(const holder of this.shadowRoot.querySelectorAll('[data-native-entity]')){if(holder.firstElementChild)continue;const id=holder.dataset.nativeEntity;if(!this.state(id))continue;const card=helpers.createCardElement({type:'entities',entities:[id],show_header_toggle:false});card.hass=this._hass;holder.appendChild(card);}},
  // Camera tiles are a bare <video> on a WebRTC session through HA's go2rtc, which only forwards the camera's packets.
  // HA's own camera card also starts an HLS stream and pulls snapshots (FFmpeg on some cameras); both run inside HA and overload a small board.
  // A watchdog reconnects a tile, with backoff, when its picture stops moving or the connection drops (for example when go2rtc restarts).
  camStart(holder){if(holder._cam||document.hidden||!holder.isConnected||!this._hass)return;const entity=holder.dataset.nativeCamera;if(!this.state(entity))return;let video=holder.querySelector('video');if(!video){video=document.createElement('video');video.muted=true;video.autoplay=true;video.playsInline=true;video.setAttribute('playsinline','');video.disablePictureInPicture=true;holder.appendChild(video);}
    const cam={entity,video,pc:null,unsub:null,timer:null,last:-1,lastMove:Date.now(),tries:0,closed:false};holder._cam=cam;(this.cams||=new Set()).add(holder);cam.watch=setInterval(()=>this.camCheck(holder),3000);this.camConnect(holder);},
  camTeardown(cam){clearTimeout(cam.timer);cam.timer=null;const unsub=cam.unsub;cam.unsub=null;if(unsub)Promise.resolve().then(unsub).catch(()=>{});try{cam.pc?.close();}catch{}cam.pc=null;},
  async camConnect(holder){const cam=holder._cam;if(!cam||cam.closed)return;this.camTeardown(cam);cam.last=-1;cam.lastMove=Date.now();const hass=this._hass;
    try{const cfg=await hass.callWS({type:'camera/webrtc/get_client_config',entity_id:cam.entity}).catch(()=>({}));if(cam.closed||cam.pc)return;
      const pc=new RTCPeerConnection(cfg.configuration||{});cam.pc=pc;pc.addTransceiver('video',{direction:'recvonly'});
      pc.ontrack=e=>{if(e.track.kind!=='video'||cam.pc!==pc)return;cam.video.srcObject=new MediaStream([e.track]);cam.video.play().catch(()=>{});};
      let session=null;const queued=[];const send=c=>hass.callWS({type:'camera/webrtc/candidate',entity_id:cam.entity,session_id:session,candidate:c}).catch(()=>{});
      pc.onicecandidate=e=>{if(!e.candidate||cam.pc!==pc)return;const c=e.candidate.toJSON();if(session)send(c);else queued.push(c);};
      const offer=await pc.createOffer();await pc.setLocalDescription(offer);if(cam.pc!==pc)return;
      const unsub=await hass.connection.subscribeMessage(m=>{if(cam.pc!==pc)return;if(m.type==='session'){session=m.session_id;queued.splice(0).forEach(send);}else if(m.type==='answer')pc.setRemoteDescription({type:'answer',sdp:m.answer}).catch(()=>{cam.lastMove=0;});else if(m.type==='candidate')pc.addIceCandidate(m.candidate).catch(()=>{});else if(m.type==='error')cam.lastMove=0;},{type:'camera/webrtc/offer',entity_id:cam.entity,offer:offer.sdp});
      if(cam.pc===pc)cam.unsub=unsub;else Promise.resolve().then(unsub).catch(()=>{});
    }catch{cam.lastMove=0;}},
  camCheck(holder){const cam=holder._cam;if(!cam)return;if(!holder.isConnected){this.camStop(holder);return;}if(document.hidden)return;const v=cam.video;
    if(v.currentTime!==cam.last){cam.last=v.currentTime;cam.lastMove=Date.now();cam.tries=0;holder.toggleAttribute('data-live',v.videoWidth>0);return;}
    const state=cam.pc?.connectionState,dead=!cam.pc||state==='failed'||state==='closed'||Date.now()-cam.lastMove>12000;
    if(dead&&!cam.timer){holder.removeAttribute('data-live');cam.tries++;const wait=Math.min(30000,1000*2**Math.min(cam.tries,5))*(0.5+Math.random()/2);cam.timer=setTimeout(()=>{cam.timer=null;this.camConnect(holder);},wait);}},
