    oldRender.call(this);if(!this.shadowRoot)return;this.renderGeneration=(this.renderGeneration||0)+1;this.unparkCameraGrid(parked);this.camSweep();this.snapRefresh();if(!this.snapTimer)this.snapTimer=setInterval(()=>{if(this.isConnected)this.snapRefresh();},600000);
    // Stop every stream while the dashboard is hidden or the screen is off; start them again when it shows.
    if(!this.cameraVisibility){this.cameraVisibility=()=>{if(!this.isConnected||!this.shadowRoot)return;if(document.hidden)[...(this.cams||[])].forEach(h=>this.camStop(h));else{this.nativeCards();this.snapRefresh();}};document.addEventListener('visibilitychange',this.cameraVisibility);}
    const meta=this.shadowRoot.querySelector('[data-meta]');if(meta){const st=this.settings();meta.innerHTML=`${asset(st.logo)?`<img class="home-logo" src="${esc(st.logo)}" alt="شعار المنزل">`:''}<div class="chip home-chip"><span class="ib">${ic('house')}</span><span><small>${greeting(st.timezone||this._hass?.config?.time_zone)}${st.city?' · '+esc(st.city):''}</small><strong>${esc(st.home_name||'منزلك')}</strong></span></div><div class="chip clock-chip"><span class="ib">${ic('clock')}</span><span data-clock>${esc(this.clock())}</span></div>`;}
    if(asset(this.settings().background))this.shadowRoot.querySelector('.shell').style.backgroundImage=`linear-gradient(rgba(8,12,18,.86),rgba(8,12,18,.86)),url("${this.settings().background}")`;
    this.shadowRoot.querySelectorAll('[data-camera]').forEach(el=>el.onclick=()=>this.navigate(el.hasAttribute('data-door')?'entry':'camera:'+el.dataset.camera));
    this.shadowRoot.querySelectorAll('[data-control]').forEach(el=>el.onclick=()=>this.runControl(el.dataset.control,el.dataset.mode));
    this.shadowRoot.querySelectorAll('[data-scope]').forEach(el=>el.onclick=()=>this.runScope(el.dataset.scope,el.dataset.on==='true'));
    this.shadowRoot.querySelectorAll('[data-new-room]').forEach(el=>el.onclick=()=>{this.newRoomFloor=el.dataset.newRoom;this.navigate('admin:registry:area:new');});
    const registryForm=this.shadowRoot.querySelector('[data-registry]');if(registryForm)registryForm.onsubmit=e=>{e.preventDefault();this.saveRegistry(registryForm);};
    this.shadowRoot.querySelectorAll('[data-more-info]').forEach(el=>el.onclick=()=>this.dispatchEvent(new CustomEvent('hass-more-info',{detail:{entityId:el.dataset.moreInfo},bubbles:true,composed:true})));
    if(this.page==='admin'&&this._hass?.user?.is_admin){const nav=document.createElement('nav');for(const [label,page] of [['معالج إضافة وتجهيز الأجهزة','admin:wizard:1'],['فحص الحالة والتخصيص','admin:diagnostics']]){const b=document.createElement('button');b.textContent=label;b.onclick=()=>this.navigate(page);nav.appendChild(b);}this.shadowRoot.querySelector('header').after(nav);}
    const refresh=this.shadowRoot.querySelector('[data-refresh-integrations]');if(refresh)refresh.onclick=()=>this.load();
    const form=this.shadowRoot.querySelector('[data-settings]');if(form)form.onsubmit=e=>{e.preventDefault();this.saveForm(form);};
    const move=(i,step)=>{const length=this.cameraIds().length;if(length)this.navigate('camera:'+((i+step+length)%length));};
