  async saveIntercom(form){const status=form.querySelector('[role=status]');try{if(!this._hass.user?.is_admin)throw Error('صلاحية الإدارة مطلوبة');const intercom=[...form.querySelectorAll('[data-intercom-device]')].map(row=>({device:row.dataset.intercomDevice,name:row.querySelector('[name=name]').value.trim(),call:row.querySelector('[name=call]').value,state:row.querySelector('[name=state]').value}));const calls=intercom.map(m=>m.call).filter(Boolean);if(new Set(calls).size!==calls.length)throw Error('لا تربط الإجراء نفسه بشاشتين');const next={...this.config,settings:{...this.settings(),intercom}};await saveSettings(this._hass,dashboardPath(),this.config,next);this.config=next;status.textContent='تم حفظ ربط الشاشات محليًا';}catch(e){status.textContent='لم يُحفظ: '+e.message;}},
  async intercomCommand(end=false){const mappings=this.intercomMappings(),source=mappings.find(m=>m.device===this.callSource),target=mappings.find(m=>m.device===this.shadowRoot.querySelector('[data-call-target]')?.value);try{if(!source)throw Error('اختر شاشة المصدر');if(!end&&(!target||target.device===source.device||target.name===source.name))throw Error('اختر شاشة أخرى مختلفة');const service=end?source.call.replace(/_call$/,'_hangup'):source.call;if(!this._hass.services?.esphome?.[service])throw Error('إجراء الشاشة غير متاح');await this._hass.callService('esphome',service,end?{}:{kiosk:target.name});this.intercomMessage=end?'أُرسل طلب إنهاء المكالمة':'أُرسل طلب الاتصال؛ انتظر حالة الرنين ورد الشاشة الأخرى';}catch(e){this.intercomMessage='تعذر الإجراء: '+e.message;}const output=this.shadowRoot.querySelector('[data-intercom-result]');if(output)output.textContent=this.intercomMessage;},
