  async addAssignmentArea(form){const status=form.querySelector('[data-create-area-status]'),button=form.querySelector('[data-create-area]');button.disabled=true;try{const name=form.querySelector('[data-new-area-name]').value.trim(),floor_id=form.querySelector('[data-new-area-floor]').value;if(!name)throw Error('اكتب اسم المساحة');await writeRegistry(this._hass,'area','',{name,icon:'',floor_id});this.registry.areas=await this._hass.callWS({type:'config/area_registry/list'});this.drawAssignments(form);status.textContent='أُضيفت المساحة. اخترها للقنوات المطلوبة ثم احفظ.';form.querySelector('[data-new-area-name]').value='';}catch(e){status.textContent='لم تُضف المساحة: '+e.message;}finally{button.disabled=false;}},
