const decorIcon=(el,page)=>{
  const p=el.dataset.page;
  if(el.hasAttribute('data-back')||el.hasAttribute('data-camera-prev'))return 'arrow-right';
  if(el.hasAttribute('data-camera-next'))return 'arrow-left';
  if(el.matches('[data-reload],[data-refresh-integrations],[data-refresh-screens],[data-network-refresh]'))return 'refresh-cw';
  if(el.getAttribute('type')==='submit')return 'save';
  if(el.matches('[data-new-room],[data-create-area]'))return 'plus';
  if(el.hasAttribute('data-intercom-call'))return 'phone-call';
  if(el.hasAttribute('data-intercom-end'))return 'phone-off';
  if(el.hasAttribute('data-more-info'))return 'activity';
  const text=el.textContent.trim();
  if(/^إلغاء/.test(text))return 'x';
  if(/^العودة إلى البرمجة/.test(text))return 'arrow-right';
  if(/^معالج/.test(text))return 'sparkles';
  if(/^فحص الحالة/.test(text))return 'activity';
  if(/شاشات التواصل/.test(text))return 'monitor-speaker';
  if(p){if(el.closest('.wizard-nav'))return '';
    if(p==='home')return /معاينة|فتح معاينة/.test(text)?'monitor-smartphone':'house';
    if(p==='admin')return /إنهاء/.test(text)?'circle-check':'settings';
    if(p==='cameras')return /الرجوع/.test(text)?'layout-grid':'layout-grid';
    if(p==='entry')return 'door-open';if(p==='intercom')return 'phone-call';if(p==='admin:intercom')return 'monitor-speaker';
    if(p==='admin:rooms')return 'layout-grid';if(/:new$/.test(p))return 'plus';if(p.startsWith('admin:registry:'))return 'pencil';
    if(p==='admin:native:networkmanual')return 'plus';if(p.startsWith('admin:native:networkdomain:'))return 'radar';if(p==='admin:native:esphome')return 'monitor-smartphone';if(p.startsWith('admin:native:'))return 'plug';
    if(p.startsWith('admin:wizard:'))return 'arrow-left';if(p==='admin:network')return 'network';if(p==='admin:diagnostics')return 'activity';
    return 'chevron-left';}
  if(el.tagName==='A'){const href=el.getAttribute('href')||'';const hit=LINK_ICONS.find(([re])=>re.test(href));return hit?hit[1]:'chevron-left';}
  return '';
};
