    root.querySelectorAll('button.setup-card[data-page^="admin:"]').forEach(card=>{if(card.querySelector('.ib'))return;const [name,tone]=SETUP_ICONS[card.dataset.page.slice(6)]||['settings',''];card.insertAdjacentHTML('afterbegin',`<span class="ib" ${tone?`data-tone="${tone}"`:''}>${ic(name)}</span>`);});
    root.querySelectorAll('button:not(.tile):not(.feed):not(.setup-card),a').forEach(el=>{if(el.querySelector('svg.i,ha-icon,.ib'))return;const name=decorIcon(el,this.page);if(name)el.insertAdjacentHTML('afterbegin',ic(name));});
