  climateCard(id){const s=this.state(id),a=s.attributes,mode=s.state,step=Number(a.target_temp_step)||1,pending=this.acPending?.[id];const target=pending??a.temperature;const ir=(this.entities||[]).find(e=>e.entity_id===id)?.platform==='smartir';const fmt=v=>Number.isFinite(Number(v))?String(Math.round(Number(v)*10)/10):'—';
    const modes=list(a.hvac_modes),order=HVAC.filter(([m])=>modes.includes(m)).filter(([m],i,arr)=>!(m==='auto'&&arr.some(([x])=>x==='heat_cool')));const fans=list(a.fan_modes);
    return `<article class="ac" data-ac="${esc(id)}" data-mode="${esc(mode)}"><div class="ac-head"><span class="ib">${ic('air-vent')}</span><span><strong>${esc(a.friendly_name||id)}</strong>${ir?'<small>ريموت IR · الحالة مفترضة</small>':''}</span></div>
    <div class="ac-temp"><button data-ac-step="1" aria-label="رفع الحرارة" ${mode==='off'?'disabled':''}>+</button><div class="ac-set"><output>${fmt(target)}°</output>${Number.isFinite(a.current_temperature)?`<small>حرارة الغرفة ${fmt(a.current_temperature)}°</small>`:''}</div><button data-ac-step="-1" aria-label="خفض الحرارة" ${mode==='off'?'disabled':''}>−</button></div>
    ${order.length?`<div class="ac-row">${order.map(([m,label,icon,tone])=>`<button data-ac-mode="${m}" aria-pressed="${mode===m}" ${tone?`data-tone="${tone}"`:''}>${ic(icon)}<span>${label}</span></button>`).join('')}</div>`:''}
    ${fans.length?`<div class="ac-row"><small>سرعة المروحة</small>${fans.map(f=>`<button data-ac-fan="${esc(f)}" aria-pressed="${a.fan_mode===f}" ${mode==='off'?'disabled':''}>${ic('fan')}<span>${esc(FAN[f]||f)}</span></button>`).join('')}</div>`:''}</article>`;},
