Object.assign(SECTION_ICONS,{'إعدادات الشاشة':'tablet-smartphone','شاشات المنزل':'tablet-smartphone','الشاشة':'monitor','المظهر':'sun-moon','شاشة التوقف':'moon-star','الصوت':'volume-2','التواصل':'phone-call','المساعد الصوتي':'mic','أدوات الشاشة':'wrench','متقدم — للإدارة فقط':'settings-2'});
