const tabletConnected=TaqaniShell.prototype.connectedCallback,tabletDisconnected=TaqaniShell.prototype.disconnectedCallback,tabletDetail=TaqaniShell.prototype.detail,tabletRender=TaqaniShell.prototype.render,tabletSignature=TaqaniShell.prototype.dataSignature;
